rules:
:root[data-theme="modern"] {
  --heading-weight: 700;
  --radius: 6px;
}
[data-theme="modern"] h1 { letter-spacing: -0.015em; }
[data-theme="modern"] h2 { letter-spacing: -0.015em; }
[data-theme="modern"] blockquote { border-left-width: 4px; }
[data-theme="modern"] hr { background: var(--quote); }
[data-theme="modern"] li::marker { color: var(--muted); }

variables:
:root[data-theme="modern"] {
  --bg: #FFFFFF;
  --surface: #F6F8FA;
  --fg: #1F2328;
  --muted: #59636E;
  --border: #D1D9E0;
  --heading: #1F2328;
  --accent: #0969DA;
  --link: #0969DA;
  --quote: #8C939A;
  --hl-keyword: #CF222E;
  --hl-string: #0A3069;
  --hl-comment: #59636E;
  --hl-number: #0550AE;
  --hl-function: #8250DF;
  --hl-type: #953800;
  --mm-node: #EEF4FC;
  --mm-border: #0969DA;
  --mm-text: #1F2328;
  --mm-line: #59636E;
  --mm-secondary: #F1ECFB;
  --mm-tertiary: #F6F8FA;
  --mm-note: #FFF8C5;
  --font-body: -apple-system, BlinkMacSystemFont, "Helvetica Neue", "PingFang TC", "PingFang SC", sans-serif;
}
@media (prefers-color-scheme: dark) {
  :root[data-theme="modern"] {
  --bg: #0D1117;
  --surface: #151B23;
  --fg: #E6EDF3;
  --muted: #9198A1;
  --border: #30363D;
  --heading: #F0F6FC;
  --accent: #4493F8;
  --link: #4493F8;
  --quote: #5B636C;
  --hl-keyword: #FF7B72;
  --hl-string: #A5D6FF;
  --hl-comment: #9198A1;
  --hl-number: #79C0FF;
  --hl-function: #D2A8FF;
  --hl-type: #FFA657;
  --mm-node: #172233;
  --mm-border: #4493F8;
  --mm-text: #E6EDF3;
  --mm-line: #9198A1;
  --mm-secondary: #221B33;
  --mm-tertiary: #151B23;
  --mm-note: #2E2A12;
  }
}
